import{c as t,Q as a,j as i,m as s}from"./chunks/framework.BvWD_EvC.js";const n="/next/screenshots/integrations-heimdall.png",u=JSON.parse('{"title":"Heimdall","description":"","frontmatter":{},"headers":[],"relativePath":"api/integrations/heimdall.md","filePath":"api/integrations/heimdall.md","lastUpdated":1788850443000}'),r={name:"api/integrations/heimdall.md"};function o(l,e,d,c,h,p){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="heimdall" tabindex="-1">Heimdall <a class="header-anchor" href="#heimdall" aria-label="Permalink to &quot;Heimdall&quot;">​</a></h1><p>LibrisLog can be integrated into <a href="https://github.com/linuxserver/Heimdall" target="_blank" rel="noreferrer">Heimdall</a>, an application dashboard and launcher for your self-hosted services, as a <a href="https://github.com/linuxserver/Heimdall-Apps" target="_blank" rel="noreferrer">LibrisLog enhanced app</a>.</p><p>The enhanced app displays your reading statistics (books read, currently reading, want-to-read, and total counts) directly on your Heimdall tile.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A running LibrisLog instance reachable <strong>from the Heimdall server</strong> (Heimdall fetches the statistics server-side, so no <a href="/next/guide/configuration.html#core-settings">CORS</a> configuration is needed)</li><li>An <a href="/next/api/integrations/#api-keys">API key</a> with access to the statistics endpoint</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><ol><li><p>In Heimdall, add a new item and pick <strong>LibrisLog</strong> as the application type (it is listed as an <em>enhanced app</em>).</p></li><li><p>In the config section of the app, enter the address of your LibrisLog instance in the <strong>URL</strong> field. The URL <strong>must end with a trailing slash</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;LIBRISLOG-URL&gt;/</span></span></code></pre></div></li><li><p>Enter your API key into the <strong>Password (API key)</strong> field.</p></li><li><p>Select which values the tile should display under <strong>Stats to show</strong>: <strong>Read</strong>, <strong>Reading</strong>, <strong>Want to read</strong>, and/or <strong>Total</strong>. Hold <kbd>Ctrl</kbd> (or <kbd>Cmd</kbd>) to select multiple entries.</p></li><li><p>Click <strong>Test</strong> to verify the connection. If everything is configured correctly, Heimdall reports <em>&quot;Successfully communicated with the API&quot;</em>.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">The URL field needs a trailing slash</p><p>The config section of a Heimdall enhanced app can be confusing: the <strong>URL</strong> field needs the address of your LibrisLog instance <strong>followed by a slash</strong>, e.g. <code>http://192.168.1.100:8000/</code>. Without the trailing slash the app cannot fetch your statistics: the tile stays empty and the <strong>Test</strong> button fails.</p></div><h2 id="result" tabindex="-1">Result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;Result&quot;">​</a></h2><p><img src="'+n+'" alt="Heimdall Widget" loading="lazy"></p>',10)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
